// PORTFOLIO-DEMO-001 — SAFE PREVIEW. DO NOT ENABLE EXECUTE WITHOUT HUMAN APPROVAL.
const task = {
  "task_id": "PORTFOLIO-DEMO-001",
  "run_mode": "PREVIEW_ONLY",
  "approved_for_execution": false,
  "expected_branch": "agent/portfolio-demo",
  "approved_manual_gates": [],
  "stages": [
    {
      "id": "CARD13.1",
      "title": "Card catalog and instance identity",
      "goal": "Parse and validate the exact CSV data, construct five typed definitions and a 13-instance starter deck; support fixed and current-Fuel (`X`) costs without representing X as numeric zero. Preserve display metadata separately from runtime semantics.",
      "acceptance_criteria": [
        "A001×5, A002×2, A003×3, A004×2, A005×1",
        "unique instance IDs",
        "robust CSV comma/quote handling, including keyword labels and whitespace",
        "tested failures for duplicate IDs, invalid cost/copies and malformed data",
        "all existing tests pass. No HUD changes."
      ],
      "initial_iteration_goal": "Inspect existing `CardDefinition`, `CardState`, CSV and their tests. Implement the smallest testable improvement (no more than four files) toward the typed catalog; run focused tests. Do not try to finish the entire STAGE in one iteration by bypassing the file budget.",
      "manual_gate_after": false
    },
    {
      "id": "CARD13.2",
      "title": "Per-player draw, hand, discard and reshuffle",
      "goal": "Implement the approved card lifecycle for each PlayerState with seeded shuffle: five cards at the beginning of the player's round, discard of remaining cards on End Turn, reshuffle discard when draw becomes empty mid-draw, no generation of nonexistent cards.",
      "acceptance_criteria": [
        "13 cards accounted for at all times except explicitly used special cases",
        "five-card base draw",
        "partial refill correctly combines old draw + shuffled discard",
        "End Turn discards unused cards and preserves normal WORLD scheduling",
        "separate player data with a minimal ownership regression",
        "full suite passes."
      ],
      "initial_iteration_goal": "Inspect existing player/card-zone and turn-flow state. Add one coherent per-player deck/zone lifecycle component or regression slice, within four files; run focused tests.",
      "manual_gate_after": false
    },
    {
      "id": "CARD13.3",
      "title": "Reusable effect composition, card-play transaction, Fuel",
      "goal": "Implement the core typed effect plan/executor and generic play-card transaction, independent of HUD. A card definition references ordered effects and parameters; selecting parameters is not committing play. A player+card-instance+options command produces an explicit result. Support fixed costs and X=current Fuel at confirmation.",
      "acceptance_criteria": [
        "only active player's owned hand instance can be played",
        "insufficient fixed Fuel rejects with no mutation/priority change",
        "successful play charges before any effect and discards exactly once",
        "impossible subeffects are skipped while remaining effects execute",
        "accepted zero-effect plays count as successful",
        "duplicate play requests cannot execute twice",
        "no parsing of description or gameplay logic in HUD",
        "full suite passes."
      ],
      "initial_iteration_goal": "Introduce one minimal typed command/result or executable effect contract with focused tests. Avoid overbuilding a speculative effect framework and keep existing authored movement untouched.",
      "manual_gate_after": false
    },
    {
      "id": "CARD13.4",
      "title": "Drive keyword and automatic legal Next JunctionIntent",
      "goal": "Use existing authored-drive for `Drive(N)` (including curves, collisions, tile interactions, Shop and terminal Finish); supply a prepared, stable random legal `Next JunctionIntent` for the actual next branching junction and reroll only after commitment.",
      "acceptance_criteria": [
        "Drive 1/2/3 distances follow authored RoadBase cells, existing routed curves and committed junctions",
        "illegal random junction directions never appear",
        "current intent remains stable until committed/changed by a card",
        "entering a junction commits intent and prepares the following junction's legal intent without changing active turn",
        "forced single-route continuations do not consume intent",
        "interrupted/non-executable Drive respects approved skip rule and Finish exception",
        "Green City-specific deterministic tests and full suite pass."
      ],
      "initial_iteration_goal": "Inspect the actual authored route planner, curve/junction route state and Green City junction tests. Implement a small focused legal-intent lookup/draw or Drive adapter with tests; do not replace the authored path planner.",
      "manual_gate_after": false
    },
    {
      "id": "CARD13.5",
      "title": "Intent Change keyword",
      "goal": "Implement `Intent Change(direction)` for a prepared next branching junction (not the already committed junction route); expose only legal options and preserve the changed intent if Drive enters the junction within the same card.",
      "acceptance_criteria": [
        "only real legal next-junction alternatives returned",
        "chosen intent is applied before the subsequent Drive effect",
        "active committed turn is unchanged",
        "future next intent prepared per CARD13.4",
        "focused deterministic tests on actual Green City topology and full suite pass."
      ],
      "initial_iteration_goal": "Add a typed query/command for legal next-junction options and state transition, with focused tests. Do not implement HUD selector.",
      "manual_gate_after": false
    },
    {
      "id": "CARD13.6",
      "title": "Lane Switch keyword and shared lane topology",
      "goal": "Implement lateral movement to one legal adjacent lane, at the same longitudinal level, using shared authored lane topology for player and civilians. Allow switching during curves and junctions, rebasing remaining active route; preserve committed turn and entered-cell interactions. Support civilians choosing randomly between both available lanes in their standard prepared WORLD plan.",
      "acceptance_criteria": [
        "correct left/right relative to facing",
        "one/two/zero adjacent lane cases",
        "one-lane road skips only Lane Switch, not subsequent Drive",
        "switch does not consume forward Drive distance",
        "entered side cell resolves collisions/rewards",
        "curve/junction continuation follows new lane without reverting",
        "civilian random left/right is seeded and plans stay stable until WORLD",
        "Green City tests and full suite pass."
      ],
      "initial_iteration_goal": "Inspect road-group data, active route state and current civilian lane-change resolver. Extract or extend one shared topology query with tests; do not add card-specific duplicate lane logic.",
      "manual_gate_after": false
    },
    {
      "id": "CARD13.7",
      "title": "Honk keyword and civilian WORLD-plan replacement",
      "goal": "Implement non-UI `Honk` reusable effect with **bounded known-route targeting** and immediate civilian response. Search nearest civilian ahead along the player's current lane to the nearest branching junction, and the immediately following road using the **already existing** JunctionIntent/committed route and corresponding lane; never continue past the next junction or roll unknown future intents. No fixed tile-count range on those two segments.",
      "acceptance_criteria": [
        "target chosen by traversal order, not geometric proximity; other lanes ignored",
        "after next road no further search",
        "one adjacent lane -> move, both -> seeded random choice, none -> remove",
        "empty Honk still successful and produces a domain event suitable for future sound",
        "if moved, invalidate old prepared WORLD plan and save a new legal FORWARD_1/FORWARD_2 plan, or STAY if neither possible (never Lane Change)",
        "no hidden WORLD reroll",
        "tests for actual route across junctions, civilian plan stability, no-target and full suite."
      ],
      "initial_iteration_goal": "Create a side-effect-free query to find a honk target on known authored route, with deterministic tests. Do not generate arbitrary future intents.",
      "manual_gate_after": false
    },
    {
      "id": "CARD13.8",
      "title": "Assemble all five cards from shared keywords",
      "goal": "Bind catalog card IDs to reusable effect sequences with player-option parameters. A001: select Drive 1/2/3. A002: auto-skip absent/obvious lane choice then Lane Switch → Drive 1/2. A003: Intent Change → Drive 1/2. A004: Honk → Drive 1. A005: charge all Fuel X, then repeat the **whole** `(Honk → Drive 3)` sequence X times; at X=0 accepted card-to-discard with zero effects.",
      "acceptance_criteria": [
        "all 13 starter instances use the five correct templates",
        "exactly the approved legal selectors/options",
        "no duplicate keyword implementations in per-card scripts",
        "A005 X=0/1/2/3 repeats full sequence, reacquires Honk target each time, stops after terminal Finish",
        "an unavailable component is skipped, remaining sequence continues",
        "targeted tests and full suite pass."
      ],
      "initial_iteration_goal": "Compose and test A001 plus one additional simple template from the shared mechanics. Continue later iterations until all five templates pass.",
      "manual_gate_after": false
    },
    {
      "id": "CARD13.9",
      "title": "Stable read/write gameplay ↔ HUD boundary",
      "goal": "Expose a small presentation-neutral projection of hand/card IDs/definitions/Fuel, prepared intent, legal choices and play eligibility; commands for play with selected options and explicit success/rejection. `End Turn` is a domain command. No `game/ui/**` modifications. UI is responsible for drag/release, discover selectors, right-click cancellation *before* final commit; backend stays unchanged until final confirmation.",
      "acceptance_criteria": [
        "immutable/read-only DTO or typed query surface sufficient to draw CardView/HandView",
        "explicit player/card-instance identity and typed selected options",
        "legal lane/intent/distance options reported consistently with execution",
        "play success/failure and updated state can be observed without UI manually subtracting Fuel or moving cards",
        "no double play",
        "acceptance/rejection, cancelling-before-submit and state-projection tests",
        "full suite."
      ],
      "initial_iteration_goal": "Stabilize and test the minimal projection/request/result surface already introduced earlier; do not implement visual HUD or input handling.",
      "manual_gate_after": false
    },
    {
      "id": "CARD13.10",
      "title": "1P Green City card-driven match loop and integration-ready handoff",
      "goal": "Wire backend lifecycle into authored Green City match (1P first): start, draw five, legal card play, End Turn, WORLD, next draw; preserve start menu and existing 2P behavior. Provide a callable domain gameplay entrypoint for the human HUD integration branch. Avoid new temporary UI beyond existing debug facilities, and do not wire `game/ui/**`.",
      "acceptance_criteria": [
        "fully automated end-to-end tests drive meaningful 1P rounds through the new card commands, without relying on debug movement keys",
        "hand/Fuel/discard/world update as specified, including multi-round reshuffle",
        "accepted card actions do not trigger WORLD prematurely and End Turn does",
        "authored map, collisions, civilian plans, Finish, Danger Zone and existing still-valid 2P regressions pass",
        "game start/menu remain functional",
        "full `run_tests.bat` passes",
        "report exact HUD-facing API, touched files, remaining integration tasks and verified tests without claiming the unintegrated HUD has been manually tested."
      ],
      "initial_iteration_goal": "Inspect the current 1P authored gameplay bootstrap and card APIs; implement one minimal end-to-end, headless card-driven scenario (or required wiring slice) with focused tests. Keep the existing human HUD out of scope.",
      "manual_gate_after": false
    }
  ]
};

if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$/.test(task.task_id)) throw new Error('Invalid task_id.');
if (!Array.isArray(task.stages) || task.stages.length === 0) throw new Error('Task must have stages.');
const ids = new Set();
for (const stage of task.stages) {
  if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$/.test(stage.id) || ids.has(stage.id)) {
    throw new Error('Stage IDs must be unique and Worker-compatible.');
  }
  ids.add(stage.id);
  if (!stage.goal?.trim() || !stage.initial_iteration_goal?.trim() ||
      !Array.isArray(stage.acceptance_criteria) || stage.acceptance_criteria.length < 1 ||
      stage.acceptance_criteria.length > 20 ||
      stage.acceptance_criteria.some(c => typeof c !== 'string' || !c.trim())) {
    throw new Error(`Invalid approved stage definition: ${stage.id}`);
  }
  if (typeof stage.manual_gate_after !== 'boolean') throw new Error('Manual gate must be boolean.');
}
if (task.run_mode !== 'PREVIEW_ONLY' && task.run_mode !== 'EXECUTE') throw new Error('Bad run_mode.');
if (task.run_mode === 'EXECUTE' && task.approved_for_execution !== true) {
  throw new Error('Real execution requires explicit approved_for_execution=true.');
}
if (task.run_mode === 'EXECUTE' && (task.task_id.startsWith('DD-ORCH-PREVIEW') ||
    task.stages.some(s => s.id.startsWith('AUTO.')))) {
  throw new Error('Replace the demo Task Spec before enabling EXECUTE.');
}
if (!Array.isArray(task.approved_manual_gates) ||
    task.approved_manual_gates.some(x => !ids.has(x))) {
  throw new Error('Invalid manual-gate approvals.');
}
return [{json: task}];

const spec = $('Task Spec — PREVIEW ONLY').first().json;
// Worker Preflight is configured to return the full HTTP response (statusCode + body).
// Normalize it before checking the Worker's fields.
const preflightResponse = $('Worker Preflight').first().json;
const preflight = preflightResponse?.body && typeof preflightResponse.body === 'object'
  ? preflightResponse.body
  : preflightResponse;
const raw = $input.first().json;
const stop = (workflow_status, message, extra = {}) => [{json:{action:'STOP',workflow_status,message,
  task_id:spec.task_id,...extra}}];
const invalid = (message) => stop('HUMAN_REQUIRED',message);
const iterationLabel = (value) => {
  let n = value;
  let s = '';
  do {s = String.fromCharCode(65 + n % 26) + s; n = Math.floor(n / 26) - 1;} while (n >= 0);
  return s;
};
const nextOrdinal = (stageId, last) => {
  if (!last || !last.iteration_id) return 0;
  const prefix = `${stageId}.`;
  if (!last.iteration_id.startsWith(prefix)) throw new Error('Last iteration does not match current stage.');
  const part = last.iteration_id.slice(prefix.length);
  if (!/^[A-Z]+$/.test(part)) throw new Error('Invalid iteration label.');
  let n = 0;
  for (const c of part) n = n * 26 + (c.charCodeAt(0) - 64);
  return n;
};
const chooseStage = (stage, iterationNumber, isRepair, repairReason = '') => {
  const iterationId = `${stage.id}.${iterationLabel(iterationNumber)}`;
  const goal = isRepair
    ? `Repair the last failing focused/full suite. Worker failure: ${String(repairReason || 'See verified history').slice(0, 800)}. Diagnose the cause, change at most four files in this iteration and run focused tests. If blocked, report HUMAN_REQUIRED. Continue following approved STAGE criteria.`
    : iterationNumber === 0
      ? stage.initial_iteration_goal
      : 'Continue the approved STAGE from the verified Worker history and current repository. Choose ONE small cohesive technical substep (at most four files) toward the acceptance criteria; fix any focused failures before new features. Report ITERATION_DONE if more work remains, STAGE_READY only when all criteria are met.';
  const payload = {
    dry_run: spec.run_mode !== 'EXECUTE',
    task_id: spec.task_id,
    stage_id: stage.id,
    iteration_id: iterationId,
    expected_branch: preflight.branch,
    expected_head: preflight.head,
    stage_goal: stage.goal,
    acceptance_criteria: stage.acceptance_criteria,
    iteration_goal: goal
  };
  return [{json:{action:'HTTP',task_id:spec.task_id,operation:'ITERATION',
    route:'/task/iteration',confirm:'task-iteration',payload,
    stage_id:stage.id,iteration_id:iterationId}}];
};
const chooseValidation = () => [{json:{action:'HTTP',task_id:spec.task_id,
  operation:'VALIDATE_STAGE',route:'/task/validate-stage',confirm:'task-validate-stage',
  payload:{dry_run:spec.run_mode !== 'EXECUTE', task_id:spec.task_id}}}];

if (Number.isInteger(preflightResponse?.statusCode) && preflightResponse.statusCode !== 200) {
  return invalid(`Worker preflight returned HTTP ${preflightResponse.statusCode}.`);
}
if (preflight.status !== 'ok' || preflight.task_orchestrator_api !== true ||
    preflight.test_runner_present !== true || preflight.codex_agent_jobs !== true) {
  return invalid(`Worker preflight invalid: status=${String(preflight.status)}, orchestrator=${String(preflight.task_orchestrator_api)}, test_runner=${String(preflight.test_runner_present)}, codex=${String(preflight.codex_agent_jobs)}.`);
}
if (preflight.repository !== 'C:\\PATH\\agent_worktree' ||
    preflight.branch !== spec.expected_branch || !/^[0-9a-f]{40}$/i.test(preflight.head || '')) {
  return invalid('Worker is not using the approved agent repo/branch/HEAD.');
}
if (!raw || !Number.isInteger(raw.statusCode) || typeof raw.body !== 'object') {
  return invalid('Invalid task-status HTTP response.');
}
const body = raw.body;
if (raw.statusCode === 400 && body?.message === 'Task State does not exist.') {
  if (preflight.clean !== true) return invalid('New TASK requires a clean agent worktree.');
  return chooseStage(spec.stages[0],0,false);
}
if (raw.statusCode !== 200 || body.status !== 'ok' || body.task_id !== spec.task_id) {
  return invalid(`Task-status HTTP failed (${raw.statusCode}): ${body?.message || 'invalid response'}`);
}
const completed = body.completed_stages;
if (!Array.isArray(completed) || completed.length > spec.stages.length ||
    completed.some((id, i) => id !== spec.stages[i].id)) {
  return invalid('Completed STAGES do not match the approved plan in order.');
}
if (body.iteration_id !== null) {
  return stop('RECOVERY_REQUIRED',`Interrupted or active iteration ${body.iteration_id}; inspect /task/lock and approve explicit resume.`,
    {recovery:body.recovery});
}
if (body.task_status === 'STAGE_VALIDATING') {
  return stop('RECOVERY_REQUIRED','Interrupted or active STAGE validation: inspect the lock and explicitly resume validation.',
    {recovery:body.recovery});
}
if (body.recovery?.worktree_status !== 'MATCHES_CHECKPOINT') {
  return invalid(`Worktree needs inspection before continuing: ${body.recovery?.worktree_status || 'unknown'}.`);
}
if (['HUMAN_REQUIRED','SYNC_REQUIRED','FAILED'].includes(body.task_status)) {
  return stop(body.task_status,`Worker stopped: ${body.task_status}. Human action required.`);
}
if (body.task_status === 'STAGE_READY') {
  if (body.next_action !== 'VALIDATE_STAGE_FULL_SUITE') return invalid('Unexpected STAGE_READY transition.');
  return chooseValidation();
}
if (body.task_status === 'STAGE_PASSED') {
  if (body.completed_stages.length === 0 ||
      body.stage_id !== body.completed_stages.at(-1)) {
    return invalid('STAGE_PASSED is inconsistent with completed stages.');
  }
  const finishedStage = spec.stages[completed.length - 1];
  if (finishedStage.manual_gate_after && !spec.approved_manual_gates.includes(finishedStage.id)) {
    return stop('MANUAL_TEST_REQUIRED',
      `Manual gate after ${finishedStage.id}. Validate the branch and add the stage ID to approved_manual_gates only after approval.`,
      {stage_id:finishedStage.id});
  }
  if (completed.length === spec.stages.length) {
    return stop('READY_FOR_REVIEW','All approved STAGES passed full validation. Human review is required; no commit, merge or COMPLETE status is written automatically.');
  }
  return chooseStage(spec.stages[completed.length],0,false);
}
if (body.task_status === 'PENDING' && completed.length === 0 && !body.last_iteration) {
  return chooseStage(spec.stages[0],0,false);
}
if (body.task_status === 'RUNNING') {
  if (!['BEGIN_NEXT_ITERATION','BEGIN_REPAIR_ITERATION'].includes(body.next_action)) {
    return invalid(`Unexpected RUNNING action: ${body.next_action}`);
  }
  const stage = spec.stages[completed.length];
  if (!stage || body.stage_id !== stage.id || !body.last_iteration ||
      body.last_iteration.iteration_id.split('.').length < 2) {
    return invalid('RUNNING stage or last iteration is inconsistent with Task Spec.');
  }
  let ordinal;
  try {ordinal=nextOrdinal(stage.id,body.last_iteration);} catch(e) {return invalid(e.message);}
  return chooseStage(stage,ordinal,body.next_action === 'BEGIN_REPAIR_ITERATION',body.last_stage_validation?.reason || '');
}
return invalid(`Unsupported persisted Task status: ${body.task_status}`);

const spec = $('Task Spec — PREVIEW ONLY').first().json;
const raw = $input.first().json;
const stop = (status, msg, data={}) => [{json:{continue_loop:false,workflow_status:status,
  task_id:spec.task_id,message:msg,...data}}];
if (!raw || !Number.isInteger(raw.statusCode) || !raw.body || typeof raw.body !== 'object') {
  return stop('HUMAN_REQUIRED','Worker task-action HTTP returned an invalid response. Inspect Worker Task State.');
}
const body = raw.body;
if (raw.statusCode !== 200 || body.task_id !== spec.task_id) {
  return stop('HUMAN_REQUIRED',
    `Task action failed (${raw.statusCode}): ${body.message || body.reason || 'unexpected response'}. Inspect state before retry.`,
    {worker_status:body.status || null});
}
if (spec.run_mode === 'PREVIEW_ONLY') {
  const okay = ['DRY_RUN_OK','STAGE_VALIDATION_DRY_RUN_OK'].includes(body.status) &&
    body.state_written === false && body.codex_started !== true && body.tests_started !== true;
  if (!okay) return stop('HUMAN_REQUIRED','Preview did not return a verified no-write response.',{worker_response:body});
  return stop('DRY_RUN_OK','Preview passed: no Codex invocation, task state change or test execution.',
    {worker_response:body});
}
if (body.status === 'blocked' || body.validation_status === 'BLOCKED') {
  return stop('HUMAN_REQUIRED',body.message || body.reason || 'Worker blocked execution.');
}
if (body.validation_status !== undefined) {
  if (!['PASSED','FAILED'].includes(body.validation_status)) {
    return stop('HUMAN_REQUIRED','Unexpected STAGE validation outcome.',{worker_response:body});
  }
  if (!['STAGE_PASSED','RUNNING'].includes(body.task_status)) {
    return stop('HUMAN_REQUIRED','Unexpected TASK status after STAGE validation.',{worker_response:body});
  }
} else if (!['RUNNING','STAGE_READY','HUMAN_REQUIRED','SYNC_REQUIRED','FAILED'].includes(body.status)) {
  return stop('HUMAN_REQUIRED','Unexpected iteration response.',{worker_response:body});
}
return [{json:{continue_loop:true,task_id:spec.task_id,worker_response:body}}];

const result = $input.first().json;
return [{json:{task_id:result.task_id, workflow_status:result.workflow_status || 'HUMAN_REQUIRED',
  message:result.message || 'The workflow stopped.',
  stage_id:result.stage_id || null,
  iteration_id:result.iteration_id || null,
  recovery:result.recovery || null,
  last_accepted_iteration:result.last_accepted_iteration || null,
  quota_info:result.quota_info || null,
  worker_response:result.worker_response || null,
  note:'The Worker owns Task State. No Git commit/push/merge is performed by this workflow.'}}];

// Readable snapshot before the long Worker HTTP request.
// This DOES NOT claim the agent finished the iteration; it is the planned step.
const x = $input.first().json;
const spec = $('Task Spec — PREVIEW ONLY').first().json;
const workerState = $('Read Worker Task State').first().json;
const stageId = x.stage_id || x.payload?.stage_id || workerState?.body?.stage_id || null;
const st = spec.stages.find(s => s.id === stageId);
const title = st?.title || 'Stage full-suite validation';
const label = x.operation === 'VALIDATE_STAGE'
  ? `${stageId || 'STAGE'} — full run_tests.bat validation`
  : x.operation === 'ITERATION'
    ? `${x.iteration_id} — ${title}`
    : x.workflow_status || 'Stopped';
return [{json:{...x, progress_label:label,
  progress_phase:x.operation === 'ITERATION' ? 'PLANNED_ITERATION' :
    x.operation === 'VALIDATE_STAGE' ? 'PLANNED_VALIDATION' : 'STOP',
  progress_note:'This is a planned operation. The live Worker monitor shows current state.'}}];

// Runs only AFTER the main TASK has already stopped at a controlled checkpoint.
// No Worker endpoints are called; this branch ONLY prepares a status email.
const r = $input.first().json;
const status = String(r.workflow_status || 'UNKNOWN');
const important = new Set([
  'MANUAL_TEST_REQUIRED', 'HUMAN_REQUIRED', 'SYNC_REQUIRED',
  'RECOVERY_REQUIRED', 'READY_FOR_REVIEW', 'FAILED', 'COMPLETE',
  'QUOTA_PAUSED', 'QUOTA_STATUS_UNKNOWN'
]);
const send_email = important.has(status);
const stage = r.stage_id || r.worker_response?.stage_id || 'N/A';
const iteration = r.iteration_id || r.worker_response?.iteration_id || 'N/A';
const subjects = {
  MANUAL_TEST_REQUIRED: 'TEST MANUALNY WYMAGANY',
  HUMAN_REQUIRED: 'POTRZEBNA DECYZJA',
  SYNC_REQUIRED: 'WYMAGANA SYNCHRONIZACJA',
  RECOVERY_REQUIRED: 'WYMAGANE WZNOWIENIE',
  READY_FOR_REVIEW: 'ZADANIE GOTOWE DO REVIEW',
  FAILED: 'ZADANIE ZATRZYMANE BLĘDEM',
  COMPLETE: 'ZADANIE ZAKONCZONE',
  QUOTA_PAUSED: 'PAUZA — NISKI LIMIT CODEXA',
  QUOTA_STATUS_UNKNOWN: 'PAUZA — NIEZNANY LIMIT CODEXA'
};
const nextSteps = {
  MANUAL_TEST_REQUIRED: 'Wykonaj uzgodnione testy manualne w Godocie. Nie zatwierdzaj bramki bez wyniku PASS.',
  HUMAN_REQUIRED: 'Sprawdz Final Result, Worker Task State oraz logi. Podejmij decyzje przed ponownym uruchomieniem.',
  SYNC_REQUIRED: 'Sprawdz zaleznosci miedzy branchami. Synchronizacja pozostaje operacja czlowieka.',
  RECOVERY_REQUIRED: 'Sprawdz /task/lock i Task State. Nie uruchamiaj ponownie bez weryfikacji checkpointu.',
  READY_FOR_REVIEW: 'Przejrzyj zmiany i testy. COMPLETE, commit i merge wymagaja osobnych decyzji czlowieka.',
  FAILED: 'Sprawdz raport walidacji i przyczyne bledu. Nie zatwierdzaj STAGE.',
  COMPLETE: 'Zadanie oznaczono jako ukonczone. Zweryfikuj zapis Workera.',
  QUOTA_PAUSED: 'Zaczekaj na odnowienie limitow, sprawdz quota probe i uruchom orchestrator ponownie. Nie uruchomiono Codexa.',
  QUOTA_STATUS_UNKNOWN: 'Sprawdz Execute Command i quota probe. Nie uruchomiono Codexa.'
};
const line = String(r.message || '').replace(/[\r\n]+/g, ' ').slice(0, 900);
const task = String(r.task_id || 'PORTFOLIO-DEMO-001');
const subject = `[Deckdrive] ${task} — ${subjects[status] || status}`;
const body = [
  'DECKDRIVE — POWIADOMIENIE Z ORCHESTRATORA', '',
  `TASK: ${task}`,
  `STAGE: ${stage}`,
  `ITERATION: ${iteration}`,
  ...(status.startsWith('QUOTA_') ? [
    `OSTATNIA ZATWIERDZONA ITERACJA: ${r.last_accepted_iteration || 'brak danych'}`,
    `NASTEPNA ITERACJA: ${r.iteration_id || 'brak danych'}`,
    `LIMIT 5H POZOSTALO: ${r.quota_info?.five_hour?.remaining_percent ?? 'UNKNOWN'}%`,
    `LIMIT TYGODNIOWY POZOSTALO: ${r.quota_info?.weekly?.remaining_percent ?? 'UNKNOWN'}%`,
    `RESET 5H UTC: ${r.quota_info?.five_hour?.reset_at_utc || 'UNKNOWN'}`,
    `RESET TYGODNIOWY UTC: ${r.quota_info?.weekly?.reset_at_utc || 'UNKNOWN'}`
  ] : []),
  `STATUS: ${status}`, '',
  `Powod: ${line || 'Brak dodatkowego komunikatu.'}`, '',
  `Nastepny krok: ${nextSteps[status] || 'Otworz n8n i sprawdz stan Workera.'}`, '',
  'Ten e-mail jest powiadomieniem, NIE zatwierdzeniem human/manual gate.',
  'Zrodlo prawdy: Worker Task State i wykonanie n8n.'
].join('\n');
return [{json:{...r,send_email,email_subject:subject,email_body:body}}];

// The SMTP node returned successfully. Do not mistake SMTP acceptance for human approval.
const original = $('Build Terminal Status Email').first().json;
const smtp = $input.first().json;
return [{json:{task_id:original.task_id,workflow_status:original.workflow_status,
  stage_id:original.stage_id || null,iteration_id:original.iteration_id || null,
  email_sent:true,notification_subject:original.email_subject,
  smtp_message_id:smtp.messageId || null,
  note:'SMTP send returned successfully; the Worker still owns Task State.'}}];

// PREVIEW_ONLY and other non-final workflow stops intentionally send no email.
const x = $input.first().json;
return [{json:{task_id:x.task_id,workflow_status:x.workflow_status,email_sent:false,
  reason:'No email for PREVIEW_ONLY/non-notifiable status.'}}];

// Strict quota gate. Runs only for an actual Codex ITERATION (not dry-run/stage tests).
// The Execute Command node replaces input with stdout: retrieve the latest planned action.
const planned = $('NEXT ACTION — stage.iteration + goal').last().json;
const workerReply = $('Read Worker Task State').last().json;
const state = workerReply?.body && typeof workerReply.body === 'object' ? workerReply.body : {};
const lastAccepted = state?.last_iteration?.iteration_id || null;
const command = $input.first()?.json || {};
const thresholds = { five_hour: 10, weekly: 5 };
const safePct = v => typeof v === 'number' && Number.isFinite(v) && v >= 0 && v <= 100;
let quota = null;
let problem = '';
if (command.exitCode !== 0) {
  problem = `Quota command did not succeed: exitCode=${String(command.exitCode ?? 'missing')}; ${String(command.error?.message || command.stderr || '').slice(0, 300)}`;
} else {
  try { quota = JSON.parse(command.stdout); }
  catch (e) { problem = `Quota probe stdout is not valid JSON: ${e.message}`; }
}
if (!problem && (quota?.status !== 'CODEX_QUOTA_READ_OK' ||
    !safePct(quota?.five_hour?.remaining_percent) ||
    !safePct(quota?.weekly?.remaining_percent))) {
  problem = 'Quota response lacks a valid 5-hour or weekly remaining_percent.';
}
const outcome = !problem && (quota.five_hour.remaining_percent <= thresholds.five_hour ||
  quota.weekly.remaining_percent <= thresholds.weekly) ? 'QUOTA_PAUSED' :
  problem ? 'QUOTA_STATUS_UNKNOWN' : 'QUOTA_OK';
if (outcome === 'QUOTA_OK') {
  return [{json:{...planned,quota_allowed:true,quota_info:{five_hour:quota.five_hour,weekly:quota.weekly}}}];
}
const reason = problem ||
  `5h remaining=${quota.five_hour.remaining_percent}% (stop <=${thresholds.five_hour}%), weekly remaining=${quota.weekly.remaining_percent}% (stop <=${thresholds.weekly}%).`;
return [{json:{quota_allowed:false,task_id:planned.task_id,
  stage_id:planned.stage_id || null,iteration_id:planned.iteration_id || null,
  workflow_status:outcome,message:reason,
  last_accepted_iteration:lastAccepted,
  quota_info:quota ? {five_hour:quota.five_hour,weekly:quota.weekly} : null,
  note:'Codex iteration was NOT started. Worker Task State was not changed.'}}];
